	Input(QIODevice &device, const Cancellation &cancellation)
		: m_device(device), m_cancellation(cancellation), m_extent(device.size())
	{
		if (m_extent < 0)
			throw Failure{Outcome::IoError, QStringLiteral("Cannot determine Bento source length.")};
	}

	qint64 extent() const { return m_extent; }

	void read(qint64 offset, qint64 length, QByteArray &bytes, QVector<ByteRange> &ranges)
	{
		checkCancellation(m_cancellation);
		if (offset < 0 || offset > m_extent || length < 0 || length > m_extent - offset)
			throw Failure{Outcome::Malformed, QStringLiteral("Bento range lies outside the captured source length.")};
		if (!m_device.seek(offset))
			throw Failure{Outcome::IoError, QStringLiteral("Cannot seek to Bento byte %1: %2").arg(offset).arg(m_device.errorString())};
		auto &range = ranges.emplaceBack(ByteRange{offset, 0});
		std::array<char, 65536> buffer; // Only the bytes filled by read() are appended.
		while (range.length < length)
		{
			checkCancellation(m_cancellation);
			const qint64 count = m_device.read(buffer.data(), std::min(length - range.length, qint64(buffer.size())));
			if (count <= 0)
				throw Failure{count == 0 && m_device.atEnd() ? Outcome::Incomplete : Outcome::IoError,
							  QStringLiteral("Cannot read Bento byte %1: %2").arg(offset + range.length).arg(m_device.errorString())};
			bytes.append(buffer.data(), count);
			range.length += count;
		}
	}

	void verify() const
	{
		checkCancellation(m_cancellation);
		if (m_device.size() != m_extent)
			throw Failure{Outcome::Incomplete, QStringLiteral("Bento source length changed during reading; check this source again.")};
	}

private:
	QIODevice &m_device;
	const Cancellation &m_cancellation;
	qint64 m_extent;

void read()
{
	if (m_input.extent() < labelSize)
		throw Failure{Outcome::Incomplete, QStringLiteral("Source is too short to contain a Bento label.")};
	const qint64 labelOffset = m_options.labelOffset == -1 ? m_input.extent() - labelSize : m_options.labelOffset;
	const auto &label = structure(QStringLiteral("Bento.Label"), labelOffset, labelSize);
	if (!label.encoding.startsWith(magic))
		throw Failure{Outcome::Malformed, QStringLiteral("No Bento label at the specified source offset.")};
	const char *p = label.encoding.constData();
	// OMF toolkit omfansic.c: Bento 1 uses little-endian container words;
	// Bento 2 uses the symmetric 0x0101 little-endian label flag.
	const quint16 flags = half(p + 8, false);
	m_result.containerBigEndian = half(p + 12, false) != 1 && (flags & 0x0101) == 0;
	m_result.major = half(p + 12, m_result.containerBigEndian);
	const quint16 minor = half(p + 14, m_result.containerBigEndian);
	if ((m_result.major != 1 && m_result.major != 2) || minor != 0)
	{
		auto &uninterpreted = m_result.structure.emplaceBack();
		uninterpreted.locator.name = QStringLiteral("Bento.UninterpretedBody");
		uninterpreted.locator.ranges.append({0, labelOffset});
		uninterpreted.state = PropertyReadState::NotRead;
		uninterpreted.bytesRetained = false;
		uninterpreted.interpretation = QStringLiteral("Body retained by source range because this label version is unsupported.");
		throw Failure{Outcome::Unsupported, QStringLiteral("Bento label version %1.%2 is not supported; extended labels are not guessed.").arg(m_result.major).arg(minor)};
	}
	if (flags & ~quint16(0x0101))
		throw Failure{Outcome::Unsupported, QStringLiteral("Unrecognised Bento label flags 0x%1.").arg(flags, 4, 16, QLatin1Char('0'))};
	m_tocOffset = word(p + 16, m_result.containerBigEndian);
	const qint64 tocLength = word(p + 20, m_result.containerBigEndian);
	m_blockSize = qint64(half(p + 10, m_result.containerBigEndian)) * 1024;
	if (!m_blockSize)
		m_blockSize = (tocLength / 1024 + 1) * 1024;
	if (m_tocOffset > labelOffset || tocLength > labelOffset - m_tocOffset)
		throw Failure{Outcome::Malformed, QStringLiteral("Bento table of contents overlaps or lies beyond its label.")};
	const auto &toc = structure(QStringLiteral("Bento.TableOfContents"), m_tocOffset, tocLength);
	m_toc = QByteArrayView(toc.encoding);
	if (m_result.major == 1)
		fixedToc();
	else
		compactToc();
	if (m_continuing)
		badValue(m_result.values.back(), QStringLiteral("Continued Bento value has no final segment."));
	const qint64 gap = labelOffset - m_tocOffset - tocLength;
	if (gap)
	{
		auto &trailing = m_result.structure.emplaceBack();
		trailing.locator.name = QStringLiteral("Bento.BytesAfterTableOfContents");
		trailing.locator.ranges.append({m_tocOffset + tocLength, gap});
		trailing.state = PropertyReadState::Present;
		trailing.bytesRetained = false;
		trailing.interpretation = QStringLiteral("Unreferenced space before the label; retained as a source range.");
	}
	if (m_options.metadataOnly)
		readMetadata();
}

void badValue(BentoValue &value, const QString &problem)
{
	value.state = PropertyReadState::Unreadable;
	value.problem = problem;
	m_result.diagnostics.append(QStringLiteral("Bento object %1 property %2: %3").arg(value.object).arg(value.property).arg(problem));
	m_result.outcome = Outcome::Malformed;
}

void append(const Segment &segment)
{
	checkCancellation(m_cancellation);
	if (m_continuing)
	{
		const auto &previous = m_result.values.back();
		if (previous.object != segment.object || previous.property != segment.property || previous.type != segment.type ||
			previous.generation != segment.generation || (segment.references && previous.referenceListObject != segment.references))
		{
			badValue(m_result.values.back(), QStringLiteral("Continued Bento value changes its object, property, type, generation or reference list."));
			m_continuing = false;
		}
	}
	if (!m_continuing)
	{
		auto &value = m_result.values.emplaceBack();
		value.object = segment.object;
		value.property = segment.property;
		value.type = segment.type;
		value.generation = segment.generation;
		value.referenceListObject = segment.references;
		value.state = PropertyReadState::Present;
	}
	auto &value = m_result.values.back();
	value.tocRanges.append(segment.framing);
	m_continuing = segment.continued;
	const bool structuralExtent = segment.object == 1 && segment.type == 19 &&
								  (segment.property == 4 || segment.property == 5 || segment.property == 7);
	const quint64 limit = segment.immediate || structuralExtent ? quint64(m_input.extent()) : quint64(m_tocOffset);
	if (segment.offset > limit || segment.length > limit - segment.offset)
	{
		badValue(value, QStringLiteral("Value range lies outside its container area; original offset and length remain in the TOC."));
		return;
	}
	if (structuralExtent && !segment.immediate)
	{
		value.bytesRetained = false;
		value.ranges.append({qint64(segment.offset), qint64(segment.length)});
		value.problem = QStringLiteral("Bento's internal TOC, container or free-space extent; retained as a range without copying those bytes.");
	}
	else if (segment.immediate)
	{
		value.bytes.append(m_toc.data() + qint64(segment.offset) - m_tocOffset, qsizetype(segment.length));
		value.ranges.append({qint64(segment.offset), qint64(segment.length)});
	}
	else if (m_options.metadataOnly)
	{
		value.bytesRetained = false;
		value.ranges.append({qint64(segment.offset), qint64(segment.length)});
		if (value.state == PropertyReadState::Present)
		{
			value.state = PropertyReadState::NotRead;
			value.problem = QStringLiteral("Value ranges indexed; metadata reading has not reached this value.");
		}
	}
	else
	{
		// Keep a failed/partial read attached to its value before propagating.
		const auto priorState = value.state;
		value.state = PropertyReadState::Unreadable;
		m_input.read(qint64(segment.offset), qint64(segment.length), value.bytes, value.ranges);
		value.state = priorState;
	}
	if ((segment.object == 1 && segment.property >= 8 && segment.property <= 10) || segment.property == 29 || segment.type == 30)
		throw Failure{Outcome::Unsupported, QStringLiteral("Bento update instructions require a target/update resolver; original value and TOC ranges are retained.")};
}

void readDeferred(BentoValue &value)
{
	if (value.state != PropertyReadState::NotRead)
		return;
	checkCancellation(m_cancellation);
	const auto declaredRanges = std::move(value.ranges);
	value.ranges.clear();
	value.bytes.clear();
	value.bytesRetained = true;
	value.state = PropertyReadState::Unreadable;
	value.problem = QStringLiteral("Metadata read interrupted; obtained bytes and their ranges are retained. The TOC preserves the complete declared extents.");
	for (const auto &range : declaredRanges)
		m_input.read(range.offset, range.length, value.bytes, value.ranges);
	value.state = PropertyReadState::Present;
	value.problem.clear();
}

void readMetadata()
{
	// Property IDs are file-local. Read their definitions before deciding
	// whether a value is media essence; a VarLenBytes/DataValue type alone
	// cannot distinguish an entire recording from a descriptor summary.
	for (auto &value : m_result.values)
	{
		checkCancellation(m_cancellation);
		if (value.property == 23 || value.property == 24)
			readDeferred(value);
	}
	// OMF toolkit omFile.c registers these seven essence property names.
	const QSet<QByteArray> essenceNames{
		"OMFI:IDAT:ImageData", "OMFI:TIFF:Data", "OMFI:TIFF:ImageData",
		"OMFI:AIFC:Data", "OMFI:AIFC:AudioData", "OMFI:WAVE:Data", "OMFI:WAVE:AudioData"};
	QHash<quint32, QSet<QByteArray>> propertyNames;
	QSet<quint32> uncertainDefinitions;
	for (const auto &value : m_result.values)
	{
		checkCancellation(m_cancellation);
		if (value.property != 24)
			continue;
		if (value.state != PropertyReadState::Present || !value.bytesRetained)
		{
			uncertainDefinitions.insert(value.object);
			continue;
		}
		const auto terminator = value.bytes.indexOf('\0');
		propertyNames[value.object].insert(terminator < 0 ? value.bytes : value.bytes.first(terminator));
	}
	for (auto &value : m_result.values)
	{
		checkCancellation(m_cancellation);
		if (value.state == PropertyReadState::Unreadable)
			continue;
		const auto names = propertyNames.constFind(value.property);
		const bool essence = names != propertyNames.cend() &&
							 std::any_of(names->cbegin(), names->cend(), [&](const QByteArray &name)
										 { return essenceNames.contains(name); });
		if (!essence)
		{
			readDeferred(value);
			continue;
		}
		value.bytes.clear();
		value.bytesRetained = false;
		value.state = PropertyReadState::Present;
		value.problem = names->size() != 1 || uncertainDefinitions.contains(value.property)
							? QStringLiteral("Conflicting property definitions include an essence property; retained by range without guessing which definition applies.")
							: QStringLiteral("Recorded media essence retained by source range; media payload bytes are not copied during metadata reading.");
	}
}

void reference(RawProperty &property, qsizetype offset, qsizetype width, qsizetype index,
			   RangeCursor &cursor, QByteArray uid = {})
{
	const quint32 key = number<quint32>(property.encoding.constData() + offset, m_bento.containerBigEndian);
	Relationship relationship;
	relationship.origin = property.locator.objectNumber;
	relationship.locator = property.locator;
	relationship.locator.ranges.clear();
	while (cursor.index < property.locator.ranges.size() &&
		   cursor.logicalStart + property.locator.ranges[cursor.index].length <= offset)
	{
		cursor.logicalStart += property.locator.ranges[cursor.index].length;
		++cursor.index;
	}
	qint64 skip = offset - cursor.logicalStart;
	qsizetype left = width;
	for (qsizetype part = cursor.index; part < property.locator.ranges.size(); ++part)
	{
		const auto &range = property.locator.ranges[part];
		if (skip >= range.length)
		{
			skip -= range.length;
			continue;
		}
		const qint64 count = qMin<qint64>(left, range.length - skip);
		relationship.locator.ranges.append({range.offset + skip, count});
		left -= count;
		skip = 0;
		if (!left)
			break;
	}
	QVariantMap recorded{{QStringLiteral("key"), key}, {QStringLiteral("index"), qlonglong(index)}, {QStringLiteral("bytes"), property.encoding.mid(offset, width)}};
	if (!uid.isEmpty())
		recorded.insert(QStringLiteral("mobId"), uid);
	relationship.recordedReference = recorded;
	relationship.referenceEncoding = QStringLiteral("OMF%1 %2-byte reference; key in Bento %3-endian order")
										 .arg(m_revision)
										 .arg(width)
										 .arg(m_bento.containerBigEndian ? QStringLiteral("big") : QStringLiteral("little"));
	quint32 target = key;
	const quint32 list = property.bento->referenceListObject;
	if (key == 0)
		relationship.explanation = QStringLiteral("Recorded null reference.");
	else if (m_bento.major >= 2 && list != 0)
	{
		const auto found = m_referenceTables.constFind(list);
		if (found == m_referenceTables.cend() || !found->readable ||
			!found->targets.contains(key) || found->ambiguousKeys.contains(key))
		{
			target = 0;
			relationship.explanation = QStringLiteral("Reference recording table is absent, unreadable or ambiguous for this key.");
		}
		else
		{
			target = found->targets.value(key);
			relationship.explanation = QStringLiteral("Resolved through recorded Bento reference table %1.").arg(list);
		}
	}
	if (target != 0 && m_objects.contains(target))
		relationship.target = target;
	else if (target != 0)
		relationship.explanation = QStringLiteral("Recorded object %1 was not found in this source.").arg(target);
	m_result.relationships.append(std::move(relationship));
}

void references(RawProperty &property, const QString &type)
{
	if (!m_revision || (type == QLatin1String("omfi:MobIndex") && m_revision != 1))
	{
		property.interpretation = QStringLiteral("Reference layout requires an established, compatible OMF object revision; original bytes retained.");
		return;
	}
	const qsizetype width = m_revision == 1 ? 8 : 4;
	RangeCursor cursor;
	if (type == QLatin1String("omfi:ObjRef"))
	{
		if (property.encoding.size() != width)
			unreadable(property, QStringLiteral("Reference width does not match the recorded OMF revision; original bytes retained."));
		else
			reference(property, 0, width, 0, cursor);
		return;
	}
	const bool index = type == QLatin1String("omfi:MobIndex");
	const qsizetype stride = index ? 12 + width : width;
	if (property.encoding.size() < 2 || (property.encoding.size() - 2) % stride != 0)
	{
		unreadable(property, QStringLiteral("Reference array has incomplete framing; original bytes retained."));
		return;
	}
	const qsizetype count = (property.encoding.size() - 2) / stride;
	property.interpretation = QStringLiteral("%1 slots established by the value's byte extent, as in the OMF toolkit; recorded count prefix retained.").arg(count);
	if (property.bento->metadataBigEndian)
	{
		const quint16 prefix = number<quint16>(property.encoding.constData(), *property.bento->metadataBigEndian);
		if (prefix != 0xffff && prefix != count)
			property.interpretation += QStringLiteral(" Recorded prefix %1 disagrees with extent; no slots discarded.").arg(prefix);
	}
	for (qsizetype slot = 0; slot < count; ++slot)
	{
		if (cancelled())
			return;
		const qsizetype offset = 2 + slot * stride;
		reference(property, offset + (index ? 12 : 0), width, slot, cursor,
				  index ? property.encoding.mid(offset, 12) : QByteArray());
	}

bool completeObject(const ParsedSource &source, const AvidObject &object)
{
	// A complete Bento read enumerates the owner's TOC entries. An unnamed
	// entry may conceal a checked property behind an unresolved dictionary
	// definition, so it cannot establish that property's absence.
	return source.outcome == ParsedSource::Outcome::Complete && !object.properties.isEmpty() &&
		   std::all_of(object.properties.cbegin(), object.properties.cend(), [&](const auto &property)
					   { return property.bento && !property.locator.name.isEmpty() &&
								property.locator.objectNumber == object.handle; });
}

	QVector<const Relationship *> entries;
};

ContentsList contentsList(const char *name, bool index = false) const
{
	ContentsList result;
	const auto *head = m_objects.value(1);
	if (!head || !m_source.omfRevision)
		return result;
	const auto values = properties(*head, {name});
	result.present = !values.isEmpty();
	if (values.size() != 1)
		return result;
	const auto *value = values.first();
	const qsizetype width = *m_source.omfRevision == OmfRevision::V1 ? 8 : 4;
	const qsizetype stride = width + (index ? 12 : 0);
	if (value->state != PropertyReadState::Present || !value->bytesRetained || !value->bento ||
		value->bento->typeName != QLatin1String(index ? "omfi:MobIndex" : "omfi:ObjRefArray") ||
		value->encoding.size() < 2 || (value->encoding.size() - 2) % stride != 0)
		return result;
	// The toolkit's array length is determined by byte extent. This also
	// accommodates its 0xffff count marker without dropping any slots.
	const qsizetype count = (value->encoding.size() - 2) / stride;
	for (const auto *edge : m_edges.value(1))
		if (edge->locator.name == QLatin1String(name))
		{
			result.entries.append(edge);
			if (!edge->target || !m_objects.contains(edge->target))
				return result;
			result.objects.insert(edge->target);
		}
	result.complete = result.entries.size() == count;
	return result;
}

void qualifyLegacyIndex(const char *name, const QSet<ObjectHandle> &expected, bool media = false)
{
	const auto list = contentsList(name, true);
	if (!list.present)
		return; // OMF1's typed indexes are optional; ObjectSpine establishes membership.
	QSet<ObjectHandle> disputed;
	bool incomparableWidth = false;
	if (!list.complete)
		disputed = expected;
	else
	{
		disputed = expected - list.objects;
		for (const auto *edge : list.entries)
		{
			const auto *owner = m_objects.value(edge->target);
			const auto uid = edge->recordedReference.toMap().value(QStringLiteral("mobId")).toByteArray();
			const auto *head = m_objects.value(1);
			const auto *index = uniqueRaw(*head, {name});
			const auto recordedId = uid.size() == 12 && index && index->bento && index->bento->metadataBigEndian
										? canonicalDatabaseId(uid, *index->bento->metadataBigEndian)
										: QString{};
			const auto ownerIds = media ? mediaIdentities(*owner) : properties(*owner, {"OMFI:MOBJ:MobID"});
			QSet<QString> ownerClaims;
			bool unreadableClaim = ownerIds.isEmpty();
			for (const auto *property : ownerIds)
			{
				const auto claim = identity(property);
				if (claim.isEmpty())
					unreadableClaim = true;
				else
					ownerClaims.insert(claim);
			}
			const auto ownerId = !unreadableClaim && ownerClaims.size() == 1 ? *ownerClaims.cbegin() : QString{};
			if (!expected.contains(edge->target) || recordedId.isEmpty() || ownerId.isEmpty())
				disputed.insert(edge->target);
			else if (ownerIds.first()->encoding.size() == 12 && recordedId != ownerId)
				disputed.insert(edge->target);
			else if (ownerIds.first()->encoding.size() == 32 && recordedId != ownerId)
				incomparableWidth = true;
		}
	}
	if (incomparableWidth)
		m_contentsDiagnostics.append(QStringLiteral("%1 contains 12-byte index UIDs referencing 32-byte Avid MobIDs. Their identity comparison is not established; recorded object references establish membership and both encodings are retained.").arg(QLatin1String(name)));
	if (!list.complete || !disputed.isEmpty())
	{
		m_contentsDiagnostics.append(QStringLiteral("%1 is unreadable or disagrees with ObjectSpine membership/recorded MobID; affected identity associations are not eligible. Raw properties and references remain available.").arg(QLatin1String(name)));
		if (media)
			m_disputedMedia = true;
		else
			m_disputedMobs += disputed;
	}
}

void establishContents()
{
	const auto fail = [&](const char *name)
	{
		m_contentsDiagnostics.append(QStringLiteral("%1 required contents list is absent, unreadable or has unresolved/unsupported ownership; owned OMF metadata is not eligible. Raw properties and references remain available.").arg(QLatin1String(name)));
	};
	if (!m_source.omfRevision)
	{
		fail("OMF HEAD");
		return;
	}
	if (*m_source.omfRevision == OmfRevision::V1)
	{
		const auto spine = contentsList("OMFI:ObjectSpine");
		if (!spine.complete)
		{
			fail("OMFI:ObjectSpine");
			return;
		}
		QSet<ObjectHandle> sources, compositions;
		for (const auto handle : spine.objects)
		{
			const auto *object = m_objects.value(handle);
			const auto cls = objectClass(*object);
			if (cls == QLatin1String("MOBJ"))
			{
				m_activeMobs.insert(handle);
				if (properties(*object, {"OMFI:MOBJ:PhysicalMedia"}).isEmpty())
					compositions.insert(handle);
				else
					sources.insert(handle);
			}
			else if (cls.isEmpty() || descriptorOrComponentClass(cls) || mobClass(cls))
			{
				fail("OMFI:ObjectSpine");
				return;
			}
			else
			{
				m_activeMedia.insert(handle);
				if (!mediaDataClass(cls))
				{
					m_disputedMedia = true;
					m_contentsDiagnostics.append(QStringLiteral("ObjectSpine media-data class %1 has no established identity interpretation; physical ownership remains unknown.").arg(cls));
				}
			}
		}
		qualifyLegacyIndex("OMFI:SourceMobs", sources);
		qualifyLegacyIndex("OMFI:CompositionMobs", compositions);
		qualifyLegacyIndex("OMFI:MediaData", m_activeMedia, true);
	}
	else
	{
		const auto mobs = contentsList("OMFI:HEAD:Mobs"), media = contentsList("OMFI:HEAD:MediaData");
		if (!mobs.complete || !media.complete)
		{
			if (!mobs.complete)
				fail("OMFI:HEAD:Mobs");
			if (!media.complete)
				fail("OMFI:HEAD:MediaData");
			return;
		}
		for (const auto handle : mobs.objects)
			if (!mobClass(objectClass(*m_objects.value(handle))))
			{
				fail("OMFI:HEAD:Mobs");
				return;
			}
		for (const auto handle : media.objects)
			if (!mediaDataClass(objectClass(*m_objects.value(handle))))
			{
				fail("OMFI:HEAD:MediaData");
				return;
			}
		m_activeMobs = mobs.objects;
		m_activeMedia = media.objects;
	}
	m_contentsComplete = true;

bool completeReferences(const AvidObject &object, const char *name, bool nullAllowed = false) const
{
	const auto values = properties(object, {name});
	if (values.isEmpty() || !m_source.omfRevision)
		return false;
	const qsizetype width = *m_source.omfRevision == OmfRevision::V1 ? 8 : 4;
	quint64 expected = 0, observed = 0;
	for (const auto *value : values)
	{
		if (value->state != PropertyReadState::Present || !value->bytesRetained || !value->bento ||
			(value->bento->typeName != QLatin1String("omfi:ObjRef") && value->bento->typeName != QLatin1String("omfi:ObjRefArray")))
			return false;
		if (value->bento->typeName == QLatin1String("omfi:ObjRef"))
		{
			if (value->encoding.size() != width)
				return false;
			++expected;
		}
		else
		{
			if (value->encoding.size() < 2 || (value->encoding.size() - 2) % width != 0)
				return false;
			expected += (value->encoding.size() - 2) / width;
		}
	}
	for (const auto *edge : m_edges.value(object.handle))
		if (edge->locator.name == QLatin1String(name))
		{
			++observed;
			if (!edge->target)
			{
				const auto recorded = edge->recordedReference.toMap();
				if (!nullAllowed || recorded.value(QStringLiteral("key")).toUInt() != 0)
					return false;
			}
		}
	return observed == expected;
}

struct ComponentTraversal
{
	QVector<const AvidObject *> objects;
	bool complete = false;
};

ComponentTraversal collectComponents(const AvidObject &owner) const
{
	QVector<ObjectHandle> pending{owner.handle};
	QVector<const AvidObject *> result;
	QSet<ObjectHandle> visited;
	bool complete = true;
	while (!pending.isEmpty())
	{
		if (m_cancellation.cancelled())
			return {std::move(result), false};
		const auto handle = pending.takeLast();
		if (visited.contains(handle))
			continue;
		visited.insert(handle);
		const auto *object = m_objects.value(handle);
		if (!object)
		{
			complete = false;
			continue;
		}
		for (const auto *name : {"OMFI:TRKG:Tracks", "OMFI:TRAK:TrackComponent", "OMFI:SEQU:Sequence",
								 "OMFI:MOBJ:Slots", "OMFI:MSLT:Segment", "OMFI:SEQU:Components", "OMFI:NEST:Slots",
								 "OMFI:SLCT:Selected", "OMFI:SLCT:Alternates", "OMFI:MGRP:Choices", "OMFI:ERAT:InputSegment"})
			if (!properties(*object, {name}).isEmpty() && !completeReferences(*object, name))
			{
				incompleteReference(*object, name);
				return {}; // A resolved branch cannot hide a missing declared component.
			}
		result.append(object);
		for (const auto *target : targets(handle, {"OMFI:TRKG:Tracks", "OMFI:TRAK:TrackComponent", "OMFI:SEQU:Sequence",
												   "OMFI:MOBJ:Slots", "OMFI:MSLT:Segment", "OMFI:SEQU:Components", "OMFI:NEST:Slots",
												   "OMFI:SLCT:Selected", "OMFI:SLCT:Alternates", "OMFI:MGRP:Choices", "OMFI:ERAT:InputSegment"}))
			pending.append(target->handle);
	}
	return {std::move(result), complete};
}

QVector<const AvidObject *> components(const AvidObject &owner) const
{

	void appendEmbedded(ParsedSource &parent, ParsedSource child, PropertyLocator embedding)
	{
		child.embedding = std::move(embedding);
		if (child.outcome != Outcome::Complete)
		{
			if (parent.outcome == Outcome::Complete)
				parent.outcome = Outcome::Incomplete;
			parent.diagnostics.append(QStringLiteral("Embedded OMF metadata was not completely interpreted; its source evidence and diagnostics are retained separately."));
		}
		parent.embeddedSources.append(std::move(child));
	}
}
